-- Query: qSolduri
-- Type: Append

INSERT INTO Solduri_Lunare ( IDP, SoldInitial, SoldPrezenta, SoldPlati, SoldRetur, Sold, SID, SIC )
SELECT Platitori.IDP, SUM(Nz(SoldInitial, 0)) AS xSoldInitial, SUM(Nz(SoldPrezenta, 0)) AS xSoldPrezenta, SUM(Nz(SoldPlati, 0)) AS xSoldPlati, SUM(Nz(SoldRetur, 0)) AS xSoldRetur, SUM(         Nz(soldprezenta, 0) + Nz(soldinitial, 0) - Nz(soldplati, 0) + Nz(soldretur, 0)     ) AS xSold, SUM(         IIf(             (                 Nz(soldprezenta, 0) + Nz(soldinitial, 0) - Nz(soldplati, 0) + Nz(soldretur, 0)             ) > 0,             (                 Nz(soldprezenta, 0) + Nz(soldinitial, 0) - Nz(soldplati, 0) + Nz(soldretur, 0)             ),             0         )     ) AS xSID, SUM(         IIf(             (                 Nz(soldprezenta, 0) + Nz(soldinitial, 0) - Nz(soldplati, 0) + Nz(soldretur, 0)             ) < 0,             ABS(                 (                     Nz(soldprezenta, 0) + Nz(soldinitial, 0) - Nz(soldplati, 0) + Nz(soldretur, 0)                 )             ),             0         )     ) AS xSIC
FROM (SELECT Solduri.IDP, SUM(Solduri.SoldInitial) AS SoldInitial, SUM(Solduri.SoldPrezenta) AS SoldPrezenta, SUM(Solduri.SoldPlati) AS SoldPlati, SUM(Solduri.SoldRetur) AS SoldRetur FROM (SELECT             Platitori.IDP,             Platitori.si AS SoldInitial,             0 AS SoldPrezenta,             0 AS SoldPlati,             0 AS SoldRetur         FROM             Platitori         WHERE             (((Platitori.si) <> 0))         UNION ALL     SELECT         Prezenta.IDP,         SUM(0) AS SoldInitial,         SUM(Prezenta.ValoareContract) AS SoldPrezenta,         SUM(0) AS SoldPlati,         (0) AS SoldRetur     FROM         Prezenta     WHERE         (             (                 (Prezenta.IDL) < forms!Prezenta!IDL             )         )     GROUP BY         Prezenta.IDP     HAVING         (             (                 (SUM(Prezenta.ValoareContract)) <> 0             )         )     UNION ALL SELECT     Plati.IDP,     SUM(0) AS SoldInitial,     SUM(0) AS SoldPrezenta,     SUM(Plati.plata) AS SoldPlati,     (0) AS SoldRetur FROM     Plati WHERE     (         ((Plati.IDL) < forms!Prezenta!IDL) AND((Plati.Anulata) = FALSE)     ) GROUP BY     Plati.IDP HAVING     (((SUM(Plati.plata)) <> 0)) UNION ALL SELECT     Retur.IDP,     SUM(0) AS SoldInitial,     SUM(0) AS SoldPrezenta,     SUM(0) AS SoldPlati,     SUM(Retur.suma) AS SoldRetur FROM     Retur WHERE     (         Retur.IDL < forms!Prezenta!IDL AND Retur.Anulat=False     ) GROUP BY     Retur.IDP HAVING     (((SUM(Retur.suma)) <> 0))     )  AS Solduri GROUP BY Solduri.IDP)  AS XSolduri RIGHT JOIN Platitori ON XSolduri.IDP = Platitori.IDP
GROUP BY Platitori.IDP
ORDER BY Platitori.IDP;
